function cloudSprite(w) {
  const c = cv(w, 14), x = c.getContext("2d");
  const n = Math.max(2, Math.round(w / 16)), bumps = [];
  for (let i = 0; i < n; i++) bumps.push((i + .5) * w / n);
  const top = [];
  for (let i = 0; i < w; i++) {
    let t = 9;
    for (const b of bumps) { const d = i + .5 - b, r = w / n * .62; if (Math.abs(d) < r) t = Math.min(t, 8 - Math.sqrt(r * r - d * d) * .75); }
    if (i < 2 || i > w - 3) t = Math.max(t, 6);
    top.push(Math.max(1, Math.round(t)));
  }
  for (let i = 0; i < w; i++) {
    x.fillStyle = "#fbfbff"; x.fillRect(i, top[i], 1, 12 - top[i]);
    x.fillStyle = "#cfd6ee"; x.fillRect(i, 10, 1, 2);
    x.fillStyle = "#4a4560"; x.fillRect(i, top[i] - 1, 1, 1); x.fillRect(i, 12, 1, 1);
  }
  x.fillStyle = "#4a4560"; x.fillRect(0, top[0], 1, 12 - top[0]); x.fillRect(w - 1, top[w - 1], 1, 12 - top[w - 1]);
  return c;
}
const CLOUDPLAT = {};
const cloudPlat = w => CLOUDPLAT[w] || (CLOUDPLAT[w] = cloudSprite(w));
