const CASTLEWALL = (() => {
  // data-center back wall: cable tray and two server racks per 96px strip
  const c = cv(96, 240), x = c.getContext("2d");
  x.fillStyle = "#1b1f2d"; x.fillRect(0, 0, 96, 240);
  x.fillStyle = "#222738"; x.fillRect(0, 0, 96, 60);
  x.fillStyle = "#151824"; x.fillRect(47, 0, 2, 60);
  x.fillStyle = "#3a3f52"; x.fillRect(0, 34, 96, 4); x.fillStyle = "#2a2f40"; x.fillRect(0, 38, 96, 1);
  [["#e0453a", 29], ["#ffd23f", 31], ["#6fd3c4", 32]].forEach(([col, y], k) => { x.fillStyle = col; for (let i = 0; i < 96; i++) x.fillRect(i, y + Math.round(Math.sin(i / 8 + k) * 1.2), 1, 1); });
  for (const rx of [10, 54]) {
    x.fillStyle = "#0f121b"; x.fillRect(rx - 1, 69, 34, 140);
    x.fillStyle = "#2a2f40"; x.fillRect(rx, 70, 32, 138);
    for (let u = 0; u < 15; u++) { x.fillStyle = "#353b50"; x.fillRect(rx + 2, 73 + u * 9, 28, 7); x.fillStyle = "#232838"; for (let v = rx + 10; v < rx + 28; v += 2) x.fillRect(v, 75 + u * 9, 1, 3); }
    x.fillStyle = "#7d8496"; x.fillRect(rx + 2, 70, 28, 2);
  }
  return c;
})();

/* ---------- levels ---------- */
const ROWS = 15, TS = 16, VIEW_H = 240;
class LB {
  constructor(w) { this.w = w; this.t = new Uint8Array(w * ROWS); this.coins = []; this.en = []; this.plats = []; this.cps = []; this.contents = {}; this.fin = (w - 16) * TS; }
  set(x, y, v) { if (x >= 0 && x < this.w && y >= 0 && y < ROWS) this.t[y * this.w + x] = v; return this; }
  g(a, b) { for (let x = a; x <= b; x++) { this.set(x, 13, G); this.set(x, 14, G); } return this; }
  row(a, b, y, v) { for (let x = a; x <= b; x++) this.set(x, y, v); return this; }
  fill(a, b, y0, y1, v) { for (let y = y0; y <= y1; y++) this.row(a, b, y, v); return this; }
  srv(x, h) { for (let y = 13 - h; y < 13; y++) { this.set(x, y, S); this.set(x + 1, y, S); } return this; }
  stairs(x, n) { for (let i = 0; i < n; i++) for (let y = 12 - i; y <= 12; y++) this.set(x + i, y, U); return this; }
  spikes(a, b) { return this.row(a, b, 12, X); }
  plat(a, b, y) { return this.row(a, b, y, P); }
  pw(x, y, what) { this.set(x, y, M); this.contents[x + "," + y] = what; return this; }
  hid(x, y, what) { this.set(x, y, V); this.contents[x + "," + y] = what; return this; }
  c(x, y) { this.coins.push({ x: x * TS + 3, y: y * TS + 3, w: 10, h: 10, got: false }); return this; }
  cs(a, b, y) { for (let x = a; x <= b; x++) this.c(x, y); return this; }
  arc(a, b, y) { const m = (a + b) / 2, r = (b - a) / 2 || 1; for (let x = a; x <= b; x++) this.c(x, y - Math.round(2 * (1 - ((x - m) / r) ** 2))); return this; }
  enemy(type, x, row) {
    const h = { spiky: 13, flaky: 10, leak: 10, loop: 14 }[type] || 11;
    const y = type === "flaky" ? row * TS : row * TS - h;
    this.en.push({ type, x: x * TS + 1, y, bx: x * TS + 1, by: y, w: 14, h, vx: 0, vy: 0, dir: -1, active: false, dead: null, t: 0, onGround: false });
    return this;
  }
  fly(x, row) { return this.enemy("flaky", x, row); }
  leak(x, row = 13) { return this.enemy("leak", x, row); }
  loop(x, row = 13) { return this.enemy("loop", x, row); }
  bug(x, row = 13) { return this.enemy("bug", x, row); }
  spk(x, row = 13) { return this.enemy("spiky", x, row); }
  mp(x, y, len, axis, range, speed = 1.4, phase = 0) { this.plats.push({ bx: x * TS, by: y * TS, w: len * TS, axis, range: range * TS, speed, phase, x: x * TS, y: y * TS, dx: 0, dy: 0 }); return this; }
  cp(x) { this.cps.push({ x: x * TS, on: false }); return this; }
  end(x) { this.fin = x * TS; this.set(x, 12, U); this.flag = true; return this; }
  arena(gateX, cageX, bossX) { this.gateX = gateX; this.cageX = cageX; this.bossX = bossX; return this; }
}

