/* ---------- background strips ---------- */
function makeHouses(pal) {
  const W = 520, H = 140, c = cv(W, H), x = c.getContext("2d"), r = rng(1234 + pal.sky[0].charCodeAt(2) * 7);
  const groundY = H - 32;
  const roof = mix("#7b3b2b", pal.haze, .3), beam = mix("#4a3428", pal.haze, .35);
  const win = pal.night ? "#ffd27a" : mix("#fff6d8", pal.haze, .25), winOff = mix("#3b3550", pal.haze, .4), winDark = mix("#3b3550", pal.haze, .4);
  const house = (hx, w, h, col, haze) => {
    const body = mix(col, pal.haze, haze), shade = mix(col, "#3b3550", .18 + haze * .2);
    const h1 = Math.round(h * .46), h2 = h - h1, top = groundY - h;
    x.fillStyle = body; x.fillRect(hx, groundY - h1, w, h1 + 40);
    x.fillStyle = mix(col, pal.haze, haze * .8); x.fillRect(hx - 3, top, w + 6, h2);
    x.fillStyle = shade; x.fillRect(hx - 3, top + h2 - 2, w + 6, 2);
    x.fillStyle = beam; x.fillRect(hx - 3, top + h2, w + 6, 1);
    const bw = Math.max(8, Math.round(w * .38)), bx = hx + Math.round((w - bw) / 2);
    x.fillStyle = body; x.fillRect(bx - 2, top + 3, bw + 4, h2 - 3);
    x.fillStyle = beam; x.fillRect(bx - 2, top + h2 - 1, bw + 4, 1); x.fillRect(bx - 2, top + 3, 1, h2 - 4); x.fillRect(bx + bw + 1, top + 3, 1, h2 - 4);
    const wcol = () => pal.night ? (r() < .55 ? win : winOff) : win;
    for (let wx = bx + 1; wx + 3 <= bx + bw; wx += 5) { x.fillStyle = wcol(); x.fillRect(wx, top + 6, 3, Math.max(4, h2 - 12)); }
    for (let wx = hx; wx + 3 <= bx - 4; wx += 6) { x.fillStyle = wcol(); x.fillRect(wx + 1, top + 6, 3, Math.max(4, h2 - 12)); }
    for (let wx = bx + bw + 5; wx + 3 <= hx + w + 1; wx += 6) { x.fillStyle = wcol(); x.fillRect(wx, top + 6, 3, Math.max(4, h2 - 12)); }
    for (let wx = hx + 3; wx + 4 <= hx + w - 3; wx += 8) { x.fillStyle = pal.night && r() < .4 ? win : winDark; x.fillRect(wx, groundY - h1 + 5, 4, 5); }
    x.fillStyle = beam; x.fillRect(hx + Math.round(w * .2), groundY - 11, 5, 11);
    for (let i = 0; i < 6; i++) { x.fillStyle = i === 5 ? mix("#3b2a26", pal.haze, .35) : roof; x.fillRect(hx - 3 - i, top - 6 + i, w + 6 + 2 * i, 1); }
  };
  let hx = -10;
  while (hx < W + 10) { const w = 26 + (r() * 18 | 0); house(hx + 8, w, 40 + (r() * 22 | 0), pal.houses[r() * pal.houses.length | 0], .55); hx += w + 14 + (r() * 10 | 0); }
  hx = -4;
  while (hx < W) { const w = 28 + (r() * 20 | 0); house(hx, w, 52 + (r() * 30 | 0), pal.houses[r() * pal.houses.length | 0], .3); hx += w + 10 + (r() * 16 | 0); }
  return c;
}
function makeHills(pal) {
  const W = 480, H = 110, c = cv(W, H), x = c.getContext("2d");
  const col = mix(pal.hills, pal.haze, .35);
  for (let i = 0; i < W; i++) {
    const t = i / W * Math.PI * 2;
    const h = 46 + Math.sin(t) * 18 + Math.sin(t * 3 + 1) * 9 + Math.sin(t * 7) * 3;
    x.fillStyle = col; x.fillRect(i, Math.round(H - h), 1, Math.round(h));
    x.fillStyle = mix(pal.hills, "#ffffff", pal.night ? .1 : .25); x.fillRect(i, Math.round(H - h), 1, 1);
  }
  return c;
}

