  if (def.boss) L.boss = makeBoss(def);
  if (EXTRA[def.id]) EXTRA[def.id](L);
  L.npcs = (NPCS[def.id] || []).map(([type, tx, say], idx) => ({ type, x: tx * TS, bx: tx * TS, say, raw: say, idx, dir: 1, face: -1, t: Math.random() * 3, near: false, talk: 0 }));
